			title: 'applyTitleAttr',
			type: 'applyTypeAttr',
			name: 'applyNameAttr',
			placeholder: 'applyPlaceholderAttr',
			role: 'applyRoleAttr',
			htmlFor: 'applyHtmlForAttr',
			width: 'applyWidthAttr',
			height: 'applyHeightAttr',
			min: 'applyMinAttr',
			max: 'applyMaxAttr',
			step: 'applyStepAttr',
			pattern: 'applyPatternAttr',
			multiple: 'applyMultipleAttr',
			required: 'applyRequiredAttr',
			autoFocus: 'applyAutoFocusAttr',
			autoComplete: 'applyAutoCompleteAttr',
			spellCheck: 'applySpellCheckAttr',
			contentEditable: 'applyContentEditableAttr',
			draggable: 'applyDraggableAttr',
			lang: 'applyLangAttr',
			dir: 'applyDirAttr',
			target: 'applyTargetAttr',
			rel: 'applyRelAttr',
			download: 'applyDownloadAttr',
			action: 'applyActionAttr',
			method: 'applyMethodAttr',
