			cols: 'applyColsAttr',
			wrap: 'applyWrapAttr',
			size: 'applySizeAttr',
			maxLength: 'applyMaxLengthAttr',
			minLength: 'applyMinLengthAttr',
			accept: 'applyAcceptAttr',
			capture: 'applyCaptureAttr',
			list: 'applyListAttr',
			form: 'applyFormAttr',
			poster: 'applyPosterAttr',
			controls: 'applyControlsAttr',
			autoPlay: 'applyAutoPlayAttr',
			loop: 'applyLoopAttr',
			muted: 'applyMutedAttr',
			preload: 'applyPreloadAttr',
			open: 'applyOpenAttr',
			cite: 'applyCiteAttr',
			dateTime: 'applyDateTimeAttr',
			start: 'applyStartAttr',
