			charset: 'applyCharsetAttr',
			label: 'applyLabelAttr',
			defaultValue: 'applyDefaultValueAttr',
			defaultChecked: 'applyDefaultCheckedAttr',
			innerHTML: 'applyInnerHTMLAttr',
			nonce: 'applyNonceAttr',
			slot: 'applySlotAttr',
			accessKey: 'applyAccessKeyAttr',
			inputMode: 'applyInputModeAttr',
			enterKeyHint: 'applyEnterKeyHintAttr',
			autoCapitalize: 'applyAutoCapitalizeAttr',
			readOnly: 'applyReadOnlyAttr',
			noValidate: 'applyNoValidateAttr',
			allowFullScreen: 'applyAllowFullScreenAttr',
