			fontFamily: 'applyFontFamilyStyle',
			fontStyle: 'applyFontStyleStyle',
			lineHeight: 'applyLineHeightStyle',
			letterSpacing: 'applyLetterSpacingStyle',
			textAlign: 'applyTextAlignStyle',
			textDecoration: 'applyTextDecorationStyle',
			textTransform: 'applyTextTransformStyle',
			overflow: 'applyOverflowStyle',
			overflowX: 'applyOverflowXStyle',
			overflowY: 'applyOverflowYStyle',
			zIndex: 'applyZIndexStyle',
			opacity: 'applyOpacityStyle',
			visibility: 'applyVisibilityStyle',
			cursor: 'applyCursorStyle',
			pointerEvents: 'applyPointerEventsStyle',
			boxShadow: 'applyBoxShadowStyle',
			transform: 'applyTransformStyle',
			transition: 'applyTransitionStyle',
			animation: 'applyAnimationStyle',
			flex: 'applyFlexStyle',
			flexDirection: 'applyFlexDirectionStyle',
			flexWrap: 'applyFlexWrapStyle',
			flexGrow: 'applyFlexGrowStyle',
			flexShrink: 'applyFlexShrinkStyle',
			justifyContent: 'applyJustifyContentStyle',
			alignItems: 'applyAlignItemsStyle',
			alignContent: 'applyAlignContentStyle',
			alignSelf: 'applyAlignSelfStyle',
			gap: 'applyGapStyle',
			gridTemplateColumns: 'applyGridTemplateColumnsStyle',
			gridTemplateRows: 'applyGridTemplateRowsStyle',
			order: 'applyOrderStyle',
			minWidth: 'applyMinWidthStyle',
			minHeight: 'applyMinHeightStyle',
			maxWidth: 'applyMaxWidthStyle',
			maxHeight: 'applyMaxHeightStyle',
			objectFit: 'applyObjectFitStyle',
			fill: 'applyFillStyle',
			stroke: 'applyStrokeStyle',
			outline: 'applyOutlineStyle',
			filter: 'applyFilterStyle',
			boxSizing: 'applyBoxSizingStyle',
			aspectRatio: 'applyAspectRatioStyle',
			whiteSpace: 'applyWhiteSpaceStyle',
			wordBreak: 'applyWordBreakStyle',
			verticalAlign: 'applyVerticalAlignStyle',
			listStyle: 'applyListStyleStyle',
			content: 'applyContentStyle',
			direction: 'applyDirectionStyle',
			userSelect: 'applyUserSelectStyle',
			resize: 'applyResizeStyle',
			textOverflow: 'applyTextOverflowStyle',
			transformOrigin: 'applyTransformOriginStyle',
			transitionDuration: 'applyTransitionDurationStyle',
			animationDuration: 'applyAnimationDurationStyle',
			flexBasis: 'applyFlexBasisStyle',
			rowGap: 'applyRowGapStyle',
			columnGap: 'applyColumnGapStyle',
			gridArea: 'applyGridAreaStyle',
			objectPosition: 'applyObjectPositionStyle',
			strokeWidth: 'applyStrokeWidthStyle',
		});
		this._eventWriters = Object.assign(Object.create(null), {
			onClick: 'applyOnClickEvent',
			onDblClick: 'applyOnDblClickEvent',
			onInput: 'applyOnInputEvent',
			onChange: 'applyOnChangeEvent',
			onSubmit: 'applyOnSubmitEvent',
			onReset: 'applyOnResetEvent',
			onFocus: 'applyOnFocusEvent',
			onBlur: 'applyOnBlurEvent',
			onKeyDown: 'applyOnKeyDownEvent',
			onKeyUp: 'applyOnKeyUpEvent',
			onKeyPress: 'applyOnKeyPressEvent',
			onMouseDown: 'applyOnMouseDownEvent',
			onMouseUp: 'applyOnMouseUpEvent',
			onMouseMove: 'applyOnMouseMoveEvent',
			onMouseEnter: 'applyOnMouseEnterEvent',
			onMouseLeave: 'applyOnMouseLeaveEvent',
			onMouseOver: 'applyOnMouseOverEvent',
			onMouseOut: 'applyOnMouseOutEvent',
			onWheel: 'applyOnWheelEvent',
			onScroll: 'applyOnScrollEvent',
			onTouchStart: 'applyOnTouchStartEvent',
			onTouchEnd: 'applyOnTouchEndEvent',
			onTouchMove: 'applyOnTouchMoveEvent',
			onTouchCancel: 'applyOnTouchCancelEvent',
			onPointerDown: 'applyOnPointerDownEvent',
			onPointerUp: 'applyOnPointerUpEvent',
			onPointerMove: 'applyOnPointerMoveEvent',
			onPointerEnter: 'applyOnPointerEnterEvent',
			onPointerLeave: 'applyOnPointerLeaveEvent',
			onContextMenu: 'applyOnContextMenuEvent',
			onDrag: 'applyOnDragEvent',
			onDragStart: 'applyOnDragStartEvent',
			onDragEnd: 'applyOnDragEndEvent',
			onDragOver: 'applyOnDragOverEvent',
			onDragEnter: 'applyOnDragEnterEvent',
			onDragLeave: 'applyOnDragLeaveEvent',
			onDrop: 'applyOnDropEvent',
			onLoad: 'applyOnLoadEvent',
			onError: 'applyOnErrorEvent',
			onAnimationEnd: 'applyOnAnimationEndEvent',
			onTransitionEnd: 'applyOnTransitionEndEvent',
			onCopy: 'applyOnCopyEvent',
			onCut: 'applyOnCutEvent',
			onPaste: 'applyOnPasteEvent',
			onPlay: 'applyOnPlayEvent',
			onPause: 'applyOnPauseEvent',
			onEnded: 'applyOnEndedEvent',
			onVolumeChange: 'applyOnVolumeChangeEvent',
			onTimeUpdate: 'applyOnTimeUpdateEvent',
			onResize: 'applyOnResizeEvent',
			onInvalid: 'applyOnInvalidEvent',
			onSelect: 'applyOnSelectEvent',
		});
		this._assignWriters = Object.assign(Object.create(null), {
			children: 'assignChildrenField',
			key: 'assignKeyField',
			ref: 'assignRefField',
			type: 'assignTypeField',
			props: 'assignPropsField',
			state: 'assignStateField',
			context: 'assignContextField',
			value: 'assignValueField',
			checked: 'assignCheckedField',
			className: 'assignClassNameField',
			class: 'assignClassField',
			style: 'assignStyleField',
			id: 'assignIdField',
			name: 'assignNameField',
			title: 'assignTitleField',
			href: 'assignHrefField',
			src: 'assignSrcField',
			disabled: 'assignDisabledField',
			hidden: 'assignHiddenField',
			placeholder: 'assignPlaceholderField',
			role: 'assignRoleField',
			tabIndex: 'assignTabIndexField',
			onClick: 'assignOnClickField',
			onInput: 'assignOnInputField',
			onChange: 'assignOnChangeField',
			onSubmit: 'assignOnSubmitField',
			dangerouslySetInnerHTML: 'assignDangerouslySetInnerHTMLField',
			defaultValue: 'assignDefaultValueField',
			defaultChecked: 'assignDefaultCheckedField',
			selected: 'assignSelectedField',
			multiple: 'assignMultipleField',
			required: 'assignRequiredField',
			readOnly: 'assignReadOnlyField',
			autoFocus: 'assignAutoFocusField',
			width: 'assignWidthField',
			height: 'assignHeightField',
			min: 'assignMinField',
			max: 'assignMaxField',
			step: 'assignStepField',
			pattern: 'assignPatternField',
			target: 'assignTargetField',
			rel: 'assignRelField',
			download: 'assignDownloadField',
			alt: 'assignAltField',
			lang: 'assignLangField',
			dir: 'assignDirField',
			action: 'assignActionField',
			method: 'assignMethodField',
