	handleBeforeDiff(vnode) {
		this._currentComponent = null;
		if (this._oldBeforeDiff) this._oldBeforeDiff(vnode);
	}

	handleRender(vnode) {
		if (this._oldBeforeRender) this._oldBeforeRender(vnode);

		this._currentComponent = vnode._component;
		this._currentIndex = 0;

		const hooks = this._currentComponent.__hooks;
		if (hooks) {
			if (this._previousComponent === this._currentComponent) {
				hooks._pendingEffects = [];
				this._currentComponent._renderCallbacks = [];
				hooks._list.forEach(hookItem => {
					if (hookItem._args) hookItem._args = undefined;
				});
			} else {
				hooks._pendingEffects.forEach(hook => this.invokeCleanup(hook));
				hooks._pendingEffects.forEach(hook => this.invokeEffect(hook));
				hooks._pendingEffects = [];
			}
		}
		this._previousComponent = this._currentComponent;
	}

	handleDiffed(vnode) {
		if (this._oldAfterDiff) this._oldAfterDiff(vnode);

		const c = vnode._component;
		if (c && c.__hooks && c.__hooks._pendingEffects.length) {
			this.afterPaint(this._afterPaintEffects.push(c));
		}
		this._currentComponent = null;
		this._previousComponent = null;
	}

	handleCommit(vnode, commitQueue) {
		commitQueue.some(component => {
			try {
				component._renderCallbacks.forEach(hook => this.invokeCleanup(hook));
				component._renderCallbacks = component._renderCallbacks.filter(cb =>
					cb._value ? this.invokeEffect(cb) : true
				);
			} catch (e) {
				commitQueue.some(c => {
					if (c._renderCallbacks) c._renderCallbacks = [];
				});
				commitQueue = [];
				options._catchError(e, component._vnode);
			}
		});

		if (this._oldCommit) this._oldCommit(vnode, commitQueue);
	}

	handleUnmount(vnode) {
		if (this._oldBeforeUnmount) this._oldBeforeUnmount(vnode);

		const c = vnode._component;
		if (c && c.__hooks) {
			let hasErrored;
			c.__hooks._list.forEach(s => {
				try {
					this.invokeCleanup(s);
				} catch (e) {
					hasErrored = e;
				}
			});
			if (hasErrored) options._catchError(hasErrored, c._vnode);
		}
	}

	getHookState(index, type) {
		if (options._hook) {
			options._hook(this._currentComponent, index, this._currentHook || type);
		}
		this._currentHook = 0;

		const hooks =
			this._currentComponent.__hooks ||
			(this._currentComponent.__hooks = {
				_list: [],
				_pendingEffects: []
			});

		if (index >= hooks._list.length) {
			hooks._list.push({});
		}
		return hooks._list[index];
	}

	useState(initialState) {
		this._currentHook = 1;
		return this.useReducer(this.invokeOrReturn.bind(this), initialState);
	}

	useReducer(reducer, initialState, init) {
		const hookState = this.getHookState(this._currentIndex++, 2);
		hookState._reducer = reducer;
		if (!hookState._component) {
			hookState._value = [
				!init
					? this.invokeOrReturn(undefined, initialState)
					: init(initialState),

				action => {
					const nextValue = hookState._reducer(hookState._value[0], action);
					if (hookState._value[0] !== nextValue) {
						hookState._value = [nextValue, hookState._value[1]];
						hookState._component.setState({});
					}
				}
			];

			hookState._component = this._currentComponent;
		}

		return hookState._value;
	}

	useEffect(callback, args) {
		const state = this.getHookState(this._currentIndex++, 3);
		if (!options._skipEffects && this.argsChanged(state._args, args)) {
			state._value = callback;
			state._args = args;

			this._currentComponent.__hooks._pendingEffects.push(state);
		}
	}

	useLayoutEffect(callback, args) {
		const state = this.getHookState(this._currentIndex++, 4);
		if (!options._skipEffects && this.argsChanged(state._args, args)) {
			state._value = callback;
			state._args = args;

			this._currentComponent._renderCallbacks.push(state);
		}
	}

	useRef(initialValue) {
		this._currentHook = 5;
		return this.useMemo(() => ({ current: initialValue }), []);
	}

	useImperativeHandle(ref, createHandle, args) {
		this._currentHook = 6;
		this.useLayoutEffect(
			() => {
				if (typeof ref == 'function') {
					ref(createHandle());
					return () => ref(null);
				} else if (ref) {
					ref.current = createHandle();
					return () => (ref.current = null);
				}
			},
			args == null ? args : args.concat(ref)
		);
	}

	useMemo(factory, args) {
		const state = this.getHookState(this._currentIndex++, 7);
		if (this.argsChanged(state._args, args)) {
			state._value = factory();
			state._args = args;
			state._factory = factory;
		}

		return state._value;
	}

	useCallback(callback, args) {
		this._currentHook = 8;
		return this.useMemo(() => callback, args);
	}

	useContext(context) {
		const provider = this._currentComponent.context[context._id];
		const state = this.getHookState(this._currentIndex++, 9);
		state._context = context;
		if (!provider) return context._defaultValue;
		if (state._value == null) {
			state._value = true;
			provider.sub(this._currentComponent);
		}
		return provider.props.value;
	}

	useDebugValue(value, formatter) {
		if (options.useDebugValue) {
			options.useDebugValue(formatter ? formatter(value) : value);
		}
	}

	useErrorBoundary(cb) {
		const state = this.getHookState(this._currentIndex++, 10);
		const errState = this.useState();
		state._value = cb;
		if (!this._currentComponent.componentDidCatch) {
			this._currentComponent.componentDidCatch = err => {
				if (state._value) state._value(err);
				errState[1](err);
			};
		}
		return [
			errState[0],
			() => {
				errState[1](undefined);
			}
		];
	}

	flushAfterPaintEffects() {
		let component;
		while ((component = this._afterPaintEffects.shift())) {
			if (!component._parentDom) continue;
			try {
				component.__hooks._pendingEffects.forEach(hook =>
					this.invokeCleanup(hook)
				);
				component.__hooks._pendingEffects.forEach(hook =>
					this.invokeEffect(hook)
				);
				component.__hooks._pendingEffects = [];
			} catch (e) {
				component.__hooks._pendingEffects = [];
				options._catchError(e, component._vnode);
			}
		}
	}

	afterNextFrame(callback) {
		const done = () => {
			clearTimeout(timeout);
			if (HAS_RAF) cancelAnimationFrame(raf);
			setTimeout(callback);
		};
		const timeout = setTimeout(done, RAF_TIMEOUT);

		let raf;
		if (HAS_RAF) {
			raf = requestAnimationFrame(done);
		}
	}

	afterPaint(newQueueLength) {
		if (newQueueLength === 1 || this._prevRaf !== options.requestAnimationFrame) {
			this._prevRaf = options.requestAnimationFrame;
			(this._prevRaf || this.afterNextFrame.bind(this))(
				this.flushAfterPaintEffects.bind(this)
			);
		}
	}

	invokeCleanup(hook) {
		const comp = this._currentComponent;
		let cleanup = hook._cleanup;
		if (typeof cleanup == 'function') {
			hook._cleanup = undefined;
			cleanup();
		}
		this._currentComponent = comp;
	}

	invokeEffect(hook) {
		const comp = this._currentComponent;
		hook._cleanup = hook._value();
		this._currentComponent = comp;
	}

	argsChanged(oldArgs, newArgs) {
		this._argsCompareOld = oldArgs;
		this._argsCompareNew = newArgs;
		return (
			!oldArgs ||
			oldArgs.length !== newArgs.length ||
			newArgs.some((arg, index) => arg !== oldArgs[index])
		);
	}

	invokeOrReturn(arg, f) {
		return typeof f == 'function' ? f(arg) : f;
	}

	prepareStateUpdate(component, update) {
		let s;
		if (component._nextState != null && component._nextState !== component.state) {
			s = component._nextState;
			this._stateReuseCount++;
		} else {
			s = component._nextState = this.mergeProperties({}, component.state);
			this._stateCloneCount++;
		}

		if (typeof update == 'function') {
			update = this.evaluateStateUpdater(update, s, component.props);
		}

		if (update) {
			this.mergeProperties(s, update);
		}

		return update;
	}

	evaluateStateUpdater(update, state, props) {
		const snapshot = this.mergeProperties({}, state);
		if (typeof update == 'function') {
			return update(snapshot, props);
		}
		return update;
	}

	markForcedRender(component) {
		component._force = true;
		this._forcedComponent = component;
		this._forceRenderCount++;
	}

	findDomSibling(vnode, childIndex) {
		if (childIndex == null) {
			return vnode._parent
				? this.findDomSibling(
						vnode._parent,
						vnode._parent._children.indexOf(vnode) + 1
				  )
				: null;
		}

		let sibling;
		for (; childIndex < vnode._children.length; childIndex++) {
			sibling = vnode._children[childIndex];

			if (sibling != null && sibling._dom != null) {
				return sibling._dom;
			}
		}

		return typeof vnode.type == 'function' ? this.findDomSibling(vnode) : null;
	}

	mergeProperties(obj, props) {
		this._assignTarget = obj;
		if (props == null) {
			return obj;
		}
		for (let key in props) {
			const writer = this._assignWriters[key];
			if (typeof writer == 'string') {
				this[writer](obj, props[key]);
			} else {
				this.assignUnknownField(obj, key, props[key]);
			}
		}
		return obj;
	}

	assignUnknownField(obj, key, value) {
		this._unknownAssignKey = key;
		this._unknownAssignValue = value;
		if (value == null) {
			obj[key] = value;
			return obj;
		}
		if (typeof value == 'number') {
			this._unknownAssignNumeric = value;
			obj[key] = value;
			return obj;
		}
		obj[key] = value;
		return obj;
	}

